// KIM-Konnektor: eine Zeile je angehängtem PDF (Arztbrief).
const sortie = [];
for (const { json: m } of $input.all()) {
  for (const pj of m.Attachments ?? []) {
    const estPdf = /pdf/i.test(pj.ContentType ?? '') || /\.pdf$/i.test(pj.FileName ?? '');
    if (!estPdf) continue;
    sortie.push({
      json: {
        id: m.ID,
        partId: pj.PartID,
        fileName: pj.FileName,
        from: m.From?.Address,
        expediteur: m.From?.Name || m.From?.Address,
        subject: m.Subject,
        date: m.Date,
      },
    });
  }
}
return sortie;

// KIM-Konnektor: Arztbrief (PDF-Text oder OCR) -> Dokument der Collection « a_verifier ».
//
// Ein Arztbrief wird IMMER in « a_verifier » abgelegt: Solange er nicht geprüft wurde (Widerspruch zu
// Allergie, Behandlung, Nierenfunktion …), wird sein Inhalt nicht als verlässlich dargestellt.
// Zuordnung zum Bewohner: Name UND Geburtsdatum (TT.MM.JJJJ) des Schreibens müssen zu GENAU EINEM
// Bewohner passen (die beiden „Heinz Müller“ unterscheiden sich nur durch das Datum). Sonst wird nicht geraten:
// Der Brief bleibt ohne patient_id, mit dem Motiv identite_inconnue oder identite_ambigue.
const residents = $('Bewohnerliste').all().map((i) => i.json);
const pieces = $('Anhänge').all();
const norm = (s) => String(s).normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();

const docs = [];
$input.all().forEach((item, i) => {
  const p = pieces[i].json;
  const texte = String(item.json.texte ?? '').trim();
  if (!texte) return;

  const t = norm(texte);
  const trouves = residents.filter((r) => t.includes(norm(r.nom)) && texte.includes(r.naissance));
  const base = {
    collection: 'a_verifier',
    source: 'kim',
    source_label: 'KIM (Arztbrief)',
    // Stabile Referenz (Absender + Dateiname): Das erneute Senden desselben Schreibens erzeugt kein Duplikat.
    source_ref: `kim/${p.from}/${p.fileName}`,
    type: 'lettre',
    titre: p.subject,
    expediteur: p.expediteur,
    statut: 'a_verifier',
    texte,
    date: new Date(p.date).toISOString(),
  };

  if (trouves.length === 1) {
    const r = trouves[0];
    docs.push({
      ...base,
      motif: 'lettre_a_verifier',
      patient_id: r.patient_id,
      chambre: r.chambre,
      patient_label: `${r.civilite} ${r.prenom} ${r.nom} (Zimmer ${r.chambre})`,
    });
  } else {
    docs.push({ ...base, motif: trouves.length === 0 ? 'identite_inconnue' : 'identite_ambigue' });
  }
});
return docs.map((json) => ({ json }));

// Eingegangene Post – ein Element je indexiertem PDF-Schreiben (zugeordnet oder nicht).
const docs = $('KIM-Dokumente').all().map((i) => i.json).filter((d) => d.source_ref);
return docs.map((d) => ({
  json: {
    source_ref: d.source_ref,
    titre: d.titre ?? 'Arztbrief',
    expediteur: d.expediteur ?? 'Absender unbekannt',
    date: d.date,
    motif: d.motif,
    patient_id: d.patient_id ?? '',
    chambre: d.chambre ?? '',
    patient_label: d.patient_label ?? '',
  },
}));

// Eingegangene Post – Meldung zu einem Schreiben, das einem Bewohner ZUGEORDNET ist. Der Bericht der Kontrollregeln (ohne KI) bestimmt den Schweregrad:
// Widerspruch = rot; kein Widerspruch = Information (das Schreiben muss weiterhin von einer Pflegekraft bestätigt werden).
const lettres = $('Zu verarbeitende Post').all().map((i) => i.json).filter((d) => d.patient_id);
const alertes = $input.all().map((item, i) => {
  const l = lettres[i];
  const r = item.json ?? {};
  const courrier = { titre: l.titre, expediteur: l.expediteur, date: l.date, ref: l.source_ref };
  const resident = l.patient_label.replace(/\s*\((?:chambre|Zimmer)[^)]*\)\s*$/, '');
  const base = { resident, chambre: l.chambre, courrier, source: 'KIM (Arztbrief)' };
  const contradictions = (Array.isArray(r.alertes) ? r.alertes : []).map((a) => String(a.message ?? '').slice(0, 300));
  if (!r.brouillon_id) {
    return {
      topic: `courrier/${l.source_ref}`, chambre: l.chambre, libelle: 'Post erhalten: Prüfung nicht möglich', patient_id: l.patient_id,
      faits: { ...base, gravite: 'attention', avertissement: 'Die automatische Prüfung dieses Schreibens ist fehlgeschlagen. Öffnen Sie „Dokument prüfen“, um sie erneut zu starten.' },
    };
  }
  return {
    topic: `courrier/${l.source_ref}`,
    chambre: l.chambre,
    libelle: contradictions.length ? 'Widerspruch in einem Schreiben' : 'Schreiben zu bestätigen: kein Widerspruch',
    patient_id: l.patient_id,
    faits: { ...base, gravite: contradictions.length ? 'rouge' : 'info', contradictions, brouillon_id: r.brouillon_id },
  };
});
return [{ json: { alertes } }];

// Eingegangene Post – Meldung zu einem NICHT zugeordneten Schreiben: Name und Geburtsdatum passen zu keinem oder zu mehreren Bewohnern.
// Das Schreiben bleibt in « a_verifier », ohne Bewohner: Es wird nie geraten.
const alertes = $input.all().map((i) => i.json).map((l) => ({
  topic: `courrier/${l.source_ref}`,
  chambre: '',
  libelle: 'Schreiben nicht zugeordnet',
  patient_id: '',
  faits: {
    gravite: 'attention',
    courrier: { titre: l.titre, expediteur: l.expediteur, date: l.date, ref: l.source_ref },
    avertissement: l.motif === 'identite_ambigue'
      ? 'Name und Geburtsdatum des Schreibens passen zu mehreren Bewohnern: Das Schreiben ist niemandem zugeordnet.'
      : 'Name und Geburtsdatum des Schreibens passen zu keinem Bewohner: Das Schreiben ist niemandem zugeordnet.',
    source: 'KIM (Arztbrief)',
  },
}));
return [{ json: { alertes } }];
